window.HOEREN_TESTS[56] = {"id":"wohnungssuche-und-makler","name":"Wohnungssuche und Makler","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Hallo Frau Schmidt, hier ist Makler Müller. Wir haben eine Wohnung gefunden, 80 Quadratmeter, nicht 60 und nicht 100, drei Zimmer, im Stadtzentrum. Die Miete ist 1200 Euro plus 200 Euro Nebenkosten. Die Besichtigung ist am Mittwoch um 17 Uhr. Bitte bestätigen Sie den Termin. Die Adresse schicke ich per E-Mail. Tschüs und bis Mittwoch!","gender":"m","q":"Wie groß ist die Wohnung?","opts":["80 Quadratmeter.","60 Quadratmeter.","100 Quadratmeter."],"correct":0},{"transcript":"Hi Lisa, hier ist Anna. Ich habe endlich eine Wohnung gefunden! Nicht im Zentrum wie geplant und nicht auf dem Land, sondern im Vorort. Aber viel günstiger, 700 Euro statt 1000. Es gibt einen Garten, es ist ruhig, perfekt für die Kinder. Einzug nächsten Monat. Komm mal vorbei und hilfst beim Möbel-Aufbauen, ja?","gender":"f","q":"Wo ist die neue Wohnung?","opts":["Im Zentrum.","Auf dem Land.","Im Vorort."],"correct":2},{"transcript":"Achtung Wohnungssuchende: Eine wichtige Information. Wir vermieten nicht mehr per Telefon und auch nicht nur persönlich ohne Unterlagen. Bitte zuerst besichtigen, dann die Bewerbung per E-Mail schicken. Mit Schufa-Auskunft und Gehaltsnachweis. Ohne diese Dokumente gibt es keine Bearbeitung. Tut uns leid, aber wir haben so viele Anfragen. Vielen Dank!","gender":"f","q":"Wie soll man sich bewerben?","opts":["Per Telefon.","Persönlich.","Per E-Mail."],"correct":2},{"transcript":"Hi Markus, hier ist Tom. Ich muss umziehen, der Vermieter kündigt mir wegen Eigenbedarf. Die Miete ist nicht zu hoch und die Wohnung ist nicht kaputt, aber ich muss raus. Ich suche dringend eine neue Wohnung, nur drei Monate Zeit. Hast du Tipps? Kennst du jemanden, der vermietet? Bitte ruf zurück, jede Hilfe ist willkommen.","gender":"m","q":"Was ist Toms Problem?","opts":["Miete zu hoch.","Vermieter kündigt.","Wohnung kaputt."],"correct":1},{"transcript":"Liebe Mieter: Die Heizung in unserem Haus wird nächste Woche repariert. Nicht nur einen Tag und nicht eine ganze Woche, sondern drei Tage ohne Heizung, Montag bis Mittwoch. Bitte warme Kleidung anziehen, vielleicht woanders übernachten. Wir entschuldigen uns. Die Reparatur ist nötig, es geht nicht anders. Vielen Dank für Ihre Geduld!","gender":"m","q":"Wie lange ohne Heizung?","opts":["Einen Tag.","Drei Tage.","Eine Woche."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer sucht was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Makler hat uns heute fünf Angebote auf den Tisch gelegt."},{"speaker":"Lisa","gender":"f","text":"Endlich haben wir einen Termin. Ich suche schon seit März und finde nichts Passendes."},{"speaker":"Lukas","gender":"m","text":"Ich nehme das WG-Zimmer nahe am Bahnhof. Die Mitbewohner sind dort ruhig."},{"speaker":"Lisa","gender":"f","text":"Für mich reicht eine Ein-Zimmer-Wohnung. Ich wohne allein und spare dabei Miete."},{"speaker":"Lukas","gender":"m","text":"Will jemand das Penthouse hoch über den Dächern?"},{"speaker":"Lisa","gender":"f","text":"Nein. Ein Penthouse wollen wir nicht. Die Miete ist uns zu hoch."},{"speaker":"Lukas","gender":"m","text":"Tom hat zwei Kinder und will raus aus der lauten Stadt."},{"speaker":"Lisa","gender":"f","text":"Tom sucht eine Familie-Wohnung mit Garten. Die Kinder brauchen draußen Platz."},{"speaker":"Lukas","gender":"m","text":"Sara liebt den Blick weit über die Dächer der Stadt."},{"speaker":"Lisa","gender":"f","text":"Sara möchte eine Maisonette mit Dachterrasse. Dort trinkt sie abends ihren Tee."},{"speaker":"Lukas","gender":"m","text":"Nehmen wir das kleine Studio neben der Wäscherei?"},{"speaker":"Lisa","gender":"f","text":"Nein. Das Studio nehmen wir auch nicht. Es hat kaum Licht zum Hof."},{"speaker":"Lukas","gender":"m","text":"Tim hat die Miete gründlich satt."},{"speaker":"Lisa","gender":"f","text":"Tim sucht ein Haus zum Kaufen. Die Bank gibt ihm schon Geld dafür."},{"speaker":"Lukas","gender":"m","text":"Dann rufe ich den Makler noch vor dem Mittag an."},{"speaker":"Lisa","gender":"f","text":"Ich schicke ihm unsere Namen gleich per Nachricht."}],"options":[{"letter":"a","text":"Bauernhaus"},{"letter":"b","text":"Familie-Wohnung mit Garten"},{"letter":"c","text":"Haus zum Kaufen"},{"letter":"d","text":"WG-Zimmer"},{"letter":"e","text":"Studio"},{"letter":"f","text":"Ein-Zimmer-Wohnung"},{"letter":"g","text":"Penthouse"},{"letter":"h","text":"Loft"},{"letter":"i","text":"Maisonette mit Dachterrasse"}],"items":[{"person":"Lukas","correct":"d"},{"person":"Lisa","correct":"f"},{"person":"Tom","correct":"b"},{"person":"Sara","correct":"i"},{"person":"Tim","correct":"c"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Mieterin","gender":"f","text":"Guten Tag, wie hoch ist die Kaution für die Wohnung, bitte?"},{"speaker":"Vermieter","gender":"m","text":"Drei Monatsmieten, also 3000 Euro. Nicht 1000 und nicht 2000, sondern drei Mieten."},{"speaker":"Mieterin","gender":"f","text":"3000 Euro ist viel. Bekomme ich die Kaution später zurück?"},{"speaker":"Vermieter","gender":"m","text":"Ja, wenn keine Schäden da sind, bekommen Sie das Geld beim Auszug zurück."},{"speaker":"Mieterin","gender":"f","text":"Gut, dann 3000 Euro Kaution. Ich überweise das vor dem Einzug. Danke!"}],"q":"Wie hoch ist die Kaution?","opts":["1000 Euro.","3000 Euro.","2000 Euro."],"correct":1},{"lines":[{"speaker":"Interessent","gender":"m","text":"Wann kann ich in die Wohnung einziehen, am 1. Mai, am 15. Mai oder erst am 1. Juni?"},{"speaker":"Maklerin","gender":"f","text":"Der 1. Mai geht nicht, die alte Mieterin wohnt dann noch. Der 1. Juni ist spät für Sie."},{"speaker":"Interessent","gender":"m","text":"Geht früher als Juni? Ich muss Mitte Mai raus aus der alten Wohnung."},{"speaker":"Maklerin","gender":"f","text":"Dann tragen wir den 15. Mai ein. Ich frage den Vermieter, aber der 15. Mai klappt meistens."},{"speaker":"Interessent","gender":"m","text":"Gut, dann Einzug am 15. Mai. Das hilft mir sehr, danke!"}],"q":"Wann ist der Einzug möglich?","opts":["1. Mai.","1. Juni.","15. Mai."],"correct":2},{"lines":[{"speaker":"Vater","gender":"m","text":"Wie viele Zimmer brauchen wir, drei, vier oder fünf? Die Kinder wollen eigene Zimmer."},{"speaker":"Mutter","gender":"f","text":"Mindestens drei, eins für jedes Kind. Aber drei allein reichen nicht für uns zwei."},{"speaker":"Vater","gender":"m","text":"Und für uns? Plus unser Schlafzimmer, also vier. Fünf ist zu teuer, oder?"},{"speaker":"Mutter","gender":"f","text":"Ja, vier Zimmer. Drei sind zu wenig, fünf können wir uns nicht leisten."},{"speaker":"Vater","gender":"m","text":"Dann suchen wir vier Zimmer. Ich schaue heute Abend noch online."}],"q":"Wie viele Zimmer?","opts":["Vier.","Drei.","Fünf."],"correct":0},{"lines":[{"speaker":"Vermieterin","gender":"f","text":"Erlauben Sie Hunde in der Wohnung? Viele Vermieter sagen nein, nur draußen."},{"speaker":"Interessent","gender":"m","text":"Eigentlich sind Hunde verboten. Aber ein kleiner Hund, der darf rein, nicht nur draußen."},{"speaker":"Vermieterin","gender":"f","text":"Mein Yorkshire-Terrier ist sehr klein, er macht wenig Lärm. Ist das okay?"},{"speaker":"Interessent","gender":"m","text":"Dann kein Problem, erlaubt, weil er klein ist. Große Hunde gehen nicht, und verboten ist er nicht."},{"speaker":"Vermieterin","gender":"f","text":"Super, dann darf er mit einziehen. Danke, das ist wichtig für uns!"}],"q":"Was ist mit dem Hund?","opts":["Verboten.","Erlaubt, weil klein.","Nur draußen."],"correct":1},{"lines":[{"speaker":"Mieter1","gender":"m","text":"Hausmeister, es gibt Lärm aus der oberen Wohnung, ich kann nicht schlafen."},{"speaker":"Hausmeister","gender":"m","text":"Wann ist der Lärm, tagsüber, morgens oder erst ab 22 Uhr in der Nacht?"},{"speaker":"Mieter1","gender":"m","text":"Nicht tagsüber und nicht morgens. Jede Nacht ab 22 Uhr, Musik und Stimmen."},{"speaker":"Hausmeister","gender":"m","text":"Ab 22 Uhr ist das zu spät. Ich spreche morgen mit dem Nachbarn, das muss aufhören."},{"speaker":"Mieter1","gender":"m","text":"Danke, bitte sagen Sie ihm das. Nach 22 Uhr will ich Ruhe."}],"q":"Wann ist der Lärm?","opts":["Ab 22 Uhr.","Tagsüber.","Morgens."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Lange, einer Immobilien-Maklerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Lange, wie ist der Wohnungsmarkt heute in der Stadt?"},{"speaker":"Lange","gender":"f","text":"Sehr schwer für Mieter. Es gibt wenige Wohnungen und die Mieten sind hoch. Viele suchen mehrere Monate. Junge Leute und Familien haben es besonders schwer in der Innenstadt."},{"speaker":"Reporter","gender":"m","text":"Was ist für die Mieter wichtig, wenn sie eine Wohnung wollen?"},{"speaker":"Lange","gender":"f","text":"Sie sollen alle Papiere dabei haben, nicht zu Hause lassen. Schufa, Gehalt, Ausweis. Und sie müssen schnell sein, weil gute Wohnungen oft am selben Tag weg sind."},{"speaker":"Reporter","gender":"m","text":"Haben Familien mit Kindern Probleme bei der Suche?"},{"speaker":"Lange","gender":"f","text":"Ja, oft. Viele Vermieter suchen lieber ruhige Mieter ohne Kinder. Das finde ich schade, denn Familien brauchen Platz. Mit Hund ist die Suche noch schwerer, leider."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie bei einer Besichtigung, Frau Lange?"},{"speaker":"Lange","gender":"f","text":"Kommen Sie pünktlich und seien Sie freundlich. Das ist sehr wichtig. Ziehen Sie sich ordentlich an und stellen Sie gute Fragen zur Wohnung. So machen Sie einen guten Eindruck."},{"speaker":"Reporter","gender":"m","text":"Wird es in Zukunft besser auf dem Markt?"},{"speaker":"Lange","gender":"f","text":"Ich glaube nicht so schnell. Man baut zu wenige neue Wohnungen, und die Städte wachsen. In fünf Jahren vielleicht, aber schnell ändert sich nichts."}],"items":[{"q":"Es gibt heute wenige Wohnungen und hohe Mieten.","correct":"ja"},{"q":"Mieter sollen ihre Papiere zu Hause lassen.","correct":"nein"},{"q":"Familien mit Kindern haben oft Probleme.","correct":"ja"},{"q":"Bei einer Besichtigung soll man pünktlich und freundlich sein.","correct":"ja"},{"q":"Frau Lange glaubt, der Markt wird schnell besser.","correct":"nein"}]}]};
